//! The tree classes the shell is given (`tree_core::tree_classes`), generated by build.rs from the
//! full catalog. Checked against the node class of design/node-core.md section 2.4, and against
//! the catalog loaded at test time, so a schema edit that the generator misses fails here.

use std::collections::BTreeSet;
use std::path::PathBuf;

use gnoblin_lua::tree_core::{ClassSpec, PropSpec, TreeCore, TreeValueKind, tree_classes};
use gnoblin_lua::tree_mirror::{LuaMirror, LuaValue};
use gnoblin_schema::{Catalog, DefaultValue, Namespace, ObjectType, Property, Type};

/// The ten tree classes, by their Lua names.
const TEN: [&str; 10] = [
    "Node",
    "Surface",
    "Window",
    "Canvas",
    "View",
    "Screen",
    "Camera",
    "Seat",
    "Workspace",
    "Lock",
];

/// The Lua name of a schema object: its name with the first letter capitalised.
fn lua_name(schema_name: &str) -> String {
    let mut chars = schema_name.chars();
    chars
        .next()
        .map(|first| first.to_uppercase().chain(chars).collect())
        .unwrap_or_default()
}

fn class<'a>(classes: &'a [ClassSpec], name: &str) -> &'a ClassSpec {
    classes
        .iter()
        .find(|class| class.name == name)
        .unwrap_or_else(|| panic!("no class `{name}`"))
}

/// Every property a class has: its own, then its base's, up the chain the shell resolves.
fn all_props<'a>(classes: &'a [ClassSpec], name: &str) -> Vec<&'a PropSpec> {
    let mut props = Vec::new();
    let mut current = Some(class(classes, name));
    while let Some(spec) = current {
        props.extend(spec.props.iter());
        current = spec.base.as_deref().map(|base| class(classes, base));
    }
    props
}

fn schema_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../gnoblin-schema/schema")
}

/// Whether a subclass's declaration of a property is the base's, so the subclass inherits it.
fn same_declaration(base: &Property, own: &Property) -> bool {
    base.name == own.name && base.ty == own.ty && base.readonly == own.readonly && base.default == own.default
}

/// The wire kind a schema type is generated as, or `None` for a type no wire carries.
fn expected_kind(ty: &Type) -> Option<TreeValueKind> {
    Some(match ty {
        Type::Bool => TreeValueKind::Bool,
        Type::Int => TreeValueKind::Int,
        Type::Uint => TreeValueKind::Uint,
        Type::Double => TreeValueKind::Double,
        Type::Text => TreeValueKind::Text,
        Type::ObjectRef(_) => TreeValueKind::Node,
        Type::List(inner) if **inner == Type::Double => TreeValueKind::ListDouble,
        Type::Bytes | Type::List(_) => return None,
    })
}

/// The value a schema default is held as, for a property of `kind`.
fn expected_default(default: &DefaultValue, kind: TreeValueKind) -> LuaValue {
    match (default, kind) {
        (DefaultValue::Bool(value), TreeValueKind::Bool) => LuaValue::Bool(*value),
        (DefaultValue::Int(value), TreeValueKind::Int) => LuaValue::Int(*value),
        (DefaultValue::Uint(value), TreeValueKind::Uint) => LuaValue::Uint(*value),
        (DefaultValue::Double(value), TreeValueKind::Double) => LuaValue::Double(*value),
        (DefaultValue::Int(value), TreeValueKind::Double) => LuaValue::Double(*value as f64),
        (DefaultValue::Uint(value), TreeValueKind::Double) => LuaValue::Double(*value as f64),
        (DefaultValue::Text(value), TreeValueKind::Text) => LuaValue::Text(value.clone()),
        (DefaultValue::List(items), TreeValueKind::ListDouble) => LuaValue::List(
            items
                .iter()
                .map(|item| match item {
                    DefaultValue::Double(value) => *value,
                    DefaultValue::Int(value) => *value as f64,
                    other => panic!("list item {other:?} is not a double"),
                })
                .collect(),
        ),
        (other, kind) => panic!("default {other:?} does not fit {kind:?}"),
    }
}

/// Sorts properties by name, for comparing a class's set of properties.
fn by_name(mut props: Vec<PropSpec>) -> Vec<PropSpec> {
    props.sort_by(|a, b| a.name.cmp(&b.name));
    props
}

/// The node class of design/node-core.md section 2.4, as the schema declares it, plus the
/// synthetic `children` the mirror derives. `tags` (`list<string>`) and `effects`
/// (`list<object:effect>`) have no wire kind, so they are not generated.
fn documented_node() -> Vec<PropSpec> {
    use TreeValueKind as K;
    let spec = |name: &str, kind, readonly, default| PropSpec {
        name: name.to_owned(),
        kind,
        readonly,
        default,
    };
    by_name(vec![
        spec("id", K::Uint, true, None),
        spec("parent", K::Node, true, None),
        spec("name", K::Text, false, Some(LuaValue::Text(String::new()))),
        spec("x", K::Double, false, Some(LuaValue::Double(0.0))),
        spec("y", K::Double, false, Some(LuaValue::Double(0.0))),
        spec("z", K::Double, false, Some(LuaValue::Double(0.0))),
        spec(
            "rotation",
            K::ListDouble,
            false,
            Some(LuaValue::List(vec![0.0, 0.0, 0.0])),
        ),
        spec("scale", K::ListDouble, false, Some(LuaValue::List(vec![1.0, 1.0, 1.0]))),
        spec("width", K::Double, false, Some(LuaValue::Double(0.0))),
        spec("height", K::Double, false, Some(LuaValue::Double(0.0))),
        spec("opacity", K::Double, false, Some(LuaValue::Double(1.0))),
        spec("visible", K::Bool, false, Some(LuaValue::Bool(true))),
        spec("clip", K::Bool, false, Some(LuaValue::Bool(false))),
        spec("input", K::Bool, false, Some(LuaValue::Bool(true))),
        spec("secure", K::Bool, false, Some(LuaValue::Bool(false))),
        spec("children", K::Nodes, true, None),
    ])
}

#[test]
fn the_ten_classes_are_present_base_first() {
    let classes = tree_classes();
    let names: BTreeSet<&str> = classes.iter().map(|class| class.name.as_str()).collect();
    let want: BTreeSet<&str> = TEN.into_iter().collect();
    assert_eq!(names, want, "the tree declares the ten classes");
    assert_eq!(classes.len(), TEN.len(), "no class is listed twice");
    for (index, spec) in classes.iter().enumerate() {
        let Some(base) = &spec.base else { continue };
        let at = classes
            .iter()
            .position(|other| &other.name == base)
            .unwrap_or_else(|| panic!("`{}` inherits from `{base}`, which is not listed", spec.name));
        assert!(at < index, "`{}` must come after its base `{base}`", spec.name);
    }
}

#[test]
fn the_core_accepts_the_generated_classes() {
    TreeCore::shared(LuaMirror::empty(), tree_classes()).expect("the generated classes are valid");
}

#[test]
fn node_has_the_documented_properties_with_their_defaults_and_flags() {
    let classes = tree_classes();
    let node = class(&classes, "Node");
    assert_eq!(node.base, None, "node is the root class");
    assert_eq!(by_name(node.props.clone()), documented_node());
    assert_eq!(node.signals, vec!["destroyed".to_owned()]);
}

#[test]
fn window_inherits_every_node_property_through_its_base() {
    let classes = tree_classes();
    let window = class(&classes, "Window");
    assert_eq!(window.base.as_deref(), Some("Node"));

    let node_names: BTreeSet<&str> = class(&classes, "Node").props.iter().map(|p| p.name.as_str()).collect();
    let reachable: BTreeSet<&str> = all_props(&classes, "Window").iter().map(|p| p.name.as_str()).collect();
    assert!(
        node_names.is_subset(&reachable),
        "every node property is reachable from Window, missing {:?}",
        node_names.difference(&reachable).collect::<Vec<_>>()
    );
    for prop in &window.props {
        assert!(
            !node_names.contains(prop.name.as_str()),
            "Window redeclares node's `{}`",
            prop.name
        );
    }
}

#[test]
fn the_table_matches_the_catalog_loaded_at_test_time() {
    let catalog = Catalog::load_dir(&schema_dir()).expect("the schema loads");
    let tree = Namespace::parse("tree").expect("the tree namespace");
    let classes = tree_classes();
    let objects: Vec<&ObjectType> = catalog
        .objects(&tree)
        .filter(|object| object.name != "tree" && !object.record)
        .collect();
    assert_eq!(classes.len(), objects.len(), "one class per tree object");

    for object in &objects {
        let spec = class(&classes, &lua_name(&object.name));
        assert_eq!(
            spec.base,
            object.base.as_deref().map(lua_name),
            "`{}` base",
            object.name
        );

        let base = object
            .base
            .as_deref()
            .map(|name| objects.iter().find(|other| other.name == name).expect("base declared"));
        let empty: &[Property] = &[];
        let base_props = base.map_or(empty, |base| base.properties.as_slice());
        let base_methods: Vec<&str> =
            base.map_or_else(Vec::new, |b| b.methods.iter().map(|m| m.name.as_str()).collect());
        let base_signals: Vec<&str> =
            base.map_or_else(Vec::new, |b| b.signals.iter().map(|s| s.name.as_str()).collect());

        let mut want: Vec<PropSpec> = object
            .properties
            .iter()
            .filter(|prop| !base_props.iter().any(|inherited| same_declaration(inherited, prop)))
            .filter_map(|prop| {
                let kind = expected_kind(&prop.ty)?;
                let default = prop.default.as_ref().map(|default| expected_default(default, kind));
                Some(PropSpec {
                    name: prop.name.clone(),
                    kind,
                    readonly: prop.readonly,
                    default,
                })
            })
            .collect();
        if object.name == "node" {
            want.extend(documented_node().into_iter().filter(|prop| prop.name == "children"));
        }
        assert_eq!(by_name(spec.props.clone()), by_name(want), "`{}` properties", spec.name);

        let mut methods: Vec<&str> = object
            .methods
            .iter()
            .map(|m| m.name.as_str())
            .filter(|name| !base_methods.contains(name))
            .collect();
        let mut got_methods: Vec<&str> = spec.methods.iter().map(String::as_str).collect();
        methods.sort_unstable();
        got_methods.sort_unstable();
        assert_eq!(got_methods, methods, "`{}` methods", spec.name);

        let mut signals: Vec<&str> = object
            .signals
            .iter()
            .map(|s| s.name.as_str())
            .filter(|name| !base_signals.contains(name))
            .collect();
        let mut got_signals: Vec<&str> = spec.signals.iter().map(String::as_str).collect();
        signals.sort_unstable();
        got_signals.sort_unstable();
        assert_eq!(got_signals, signals, "`{}` signals", spec.name);
    }
}

#[test]
fn the_published_stub_names_no_tree_member() {
    let stub = gnoblin_lua::stub();
    assert!(
        !stub.contains("tree."),
        "the owner-only tree must not reach the published stub"
    );
}
